    public static RatePlan create(RatePlanType type) {
        RatePlan plan = PLANS.get(type);

        try {
            return plan.getClass().getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Erro ao criar plano de tarifa", e);
        }
    }
}

