        if (portEnv != null && !portEnv.isEmpty()) {
            try {
                return Integer.parseInt(portEnv);
            } catch (NumberFormatException e) {
                System.err.println("Porta inválida na variável PORT, usando padrão 7070");
            }
        }
        return 7070;
    }
